#include <iostream>

int main() {
    // 1. boolalpha and noboolalpha
    bool flag = true;
    std::cout << "Default bool: " << flag << '\n';
    std::cout << "With boolalpha: " << std::boolalpha << flag << '\n';
    std::cout << std::noboolalpha;
    std::cout << "With noboolalpha: " << flag << "\n\n";

    // 2. Saving and restoring format state via flags()
    int intVal = 1000;
    double dblVal = 0.0947628;

    std::ios_base::fmtflags originalFlags = std::cout.flags();
    std::cout << "Original format: " << intVal << "\t" << dblVal << '\n';

    std::cout << std::showbase << std::oct << std::scientific;
    std::cout << "Modified format: " << intVal << "\t" << dblVal << '\n';

    std::cout.flags(originalFlags);
    std::cout << "Restored format: " << intVal << "\t" << dblVal << '\n';

    return 0;
}

#include <iostream>
#include <sstream>

int main() {
    // Simulate input using an in-memory istringstream
    std::istringstream input("abc 42");
    int value = 0;

    std::cout << "Initial state:" << '\n';
    std::cout << "  good(): " << input.good() << ", fail(): " << input.fail() << '\n';

    // Attempt to extract an integer from string "abc"
    input >> value;

    std::cout << "After failed extraction:" << '\n';
    std::cout << "  rdstate() == failbit: " << ((input.rdstate() & std::ios_base::failbit) != 0) << '\n';
    std::cout << "  eof():  " << input.eof() << '\n';
    std::cout << "  fail(): " << input.fail() << '\n';
    std::cout << "  bad():  " << input.bad() << '\n';
    std::cout << "  good(): " << input.good() << '\n';
    std::cout << "  operator!: " << (!input) << '\n';

    // Reset stream state and skip bad token
    input.clear();
    std::string skippedToken;
    input >> skippedToken; // consume "abc"

    // Try reading again
    input >> value; // reads 42
    std::cout << "After clear() and reading remaining valid int:" << '\n';
    std::cout << "  fail(): " << input.fail() << ", value: " << value << '\n';

    return 0;
}
